// ONE STICKER — glyph sources (pure TS, deterministic).
//
// "Sans" = Noto Sans 400 / 700 / 900 (Latin, Cyrillic, Vietnamese, punctuation) + Noto Sans TC 400
// (kana, CJK punctuation, full-width and half-width forms), shipped as VECTOR OUTLINES
// (sansOutlines.*.ts, generated by scripts/gen-sans-outlines.mjs, each its own lazy chunk) and
// rasterized HERE in pure TypeScript: flatten the curves, nonzero scanline at pixel centres. No
// canvas, no system font → the same bits on iPhone, Android, laptop and in the tests.
//
// Chinese ideographs come from the committed Noto Sans CJK TC Regular cell atlases (18/20/24/32,
// em cells, baseline at 0.88 em — the same source the compact layout uses), magnified by whole
// numbers for bigger text; Bold / Extra thicken the strokes by a few dots (dilation), the same
// way for the kana outlines, so 田中さん reads as ONE weight.
//
// Anything else (Hangul, Thai, Arabic, Hebrew, Devanagari, rare ideographs …) is drawn by the
// FALLBACK drawer (a canvas with the device's fonts, which shapes Thai marks and joins Arabic
// letters correctly) into the same 1-bit picture. Only the fallback can differ between devices.
import type { GlyphAtlas } from "./stickerRaster";

export interface SansFace { upm: number; asc: number; desc: number; g: Record<number, string> }
export type SansWeight = 400 | 700 | 900;

// ── Lazy loaders (one chunk per weight + one for the kana/full-width set) ─────────────────────
const faces: Partial<Record<SansWeight | "cjkx", SansFace>> = {};
const inflight: Partial<Record<SansWeight | "cjkx", Promise<SansFace>>> = {};
function importFace(k: SansWeight | "cjkx"): Promise<{ SANS_FACE: SansFace }> {
  switch (k) {
    case 400: return import("./sansOutlines.400");
    case 700: return import("./sansOutlines.700");
    case 900: return import("./sansOutlines.900");
    default: return import("./sansOutlines.cjkx");
  }
}
export function loadSansFace(k: SansWeight | "cjkx"): Promise<SansFace> {
  const have = faces[k];
  if (have) return Promise.resolve(have);
  let p = inflight[k];
  if (!p) {
    p = importFace(k).then(
      (m) => { faces[k] = m.SANS_FACE; return m.SANS_FACE; },
      (err) => { inflight[k] = undefined; throw err; }, // retry-able on the next print
    );
    inflight[k] = p;
  }
  return p;
}
export const getSansFace = (k: SansWeight | "cjkx"): SansFace | null => faces[k] ?? null;
/** Tests / pre-warmed callers: install a face directly. */
export function installSansFace(k: SansWeight | "cjkx", f: SansFace): void { faces[k] = f; }

// ── Outline → 1-bit glyph ─────────────────────────────────────────────────────────────────────
// A rasterized glyph: `buf` packed MSB-first, bit 1 = ink. (x0, y0) = the bitmap's top-left
// relative to the pen on the baseline (y DOWN). adv = the advance in dots (fractional).
export interface GlyphBits { w: number; h: number; rowBytes: number; buf: Uint8Array; x0: number; y0: number; adv: number }
export const EMPTY_GLYPH = (adv: number): GlyphBits => ({ w: 0, h: 0, rowBytes: 0, buf: new Uint8Array(0), x0: 0, y0: 0, adv });

interface Pt { x: number; y: number }
// Decode the relative path (see gen-sans-outlines.mjs): every point of one command is a delta
// from that command's START point. Returns contours as absolute polylines (font units).
function parseOutline(path: string, steps: number): Pt[][] {
  const tok = path.match(/[MLQCZ]|-?\d+/g) ?? [];
  const contours: Pt[][] = [];
  let cur: Pt[] | null = null;
  let cx = 0, cy = 0, sx = 0, sy = 0;
  let i = 0;
  const num = () => Number(tok[i++]);
  while (i < tok.length) {
    const c = tok[i++];
    if (c === "M") { const x = cx + num(), y = cy + num(); cur = [{ x, y }]; contours.push(cur); cx = sx = x; cy = sy = y; }
    else if (c === "L") { const x = cx + num(), y = cy + num(); cur?.push({ x, y }); cx = x; cy = y; }
    else if (c === "Q") {
      const x1 = cx + num(), y1 = cy + num(), x = cx + num(), y = cy + num();
      for (let s = 1; s <= steps; s++) { const t = s / steps, u = 1 - t; cur?.push({ x: u * u * cx + 2 * u * t * x1 + t * t * x, y: u * u * cy + 2 * u * t * y1 + t * t * y }); }
      cx = x; cy = y;
    } else if (c === "C") {
      const x1 = cx + num(), y1 = cy + num(), x2 = cx + num(), y2 = cy + num(), x = cx + num(), y = cy + num();
      for (let s = 1; s <= steps; s++) { const t = s / steps, u = 1 - t; cur?.push({ x: u * u * u * cx + 3 * u * u * t * x1 + 3 * u * t * t * x2 + t * t * t * x, y: u * u * u * cy + 3 * u * u * t * y1 + 3 * u * t * t * y2 + t * t * t * y }); }
      cx = x; cy = y;
    } else if (c === "Z") { if (cur && (cx !== sx || cy !== sy)) cur.push({ x: sx, y: sy }); cx = sx; cy = sy; }
  }
  return contours;
}

// Nonzero scanline fill at pixel centres → packed bits. Coordinates already in dots.
function fillContours(contours: Pt[][]): { w: number; h: number; rowBytes: number; buf: Uint8Array; x0: number; y0: number } | null {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const c of contours) for (const p of c) { if (p.x < minX) minX = p.x; if (p.x > maxX) maxX = p.x; if (p.y < minY) minY = p.y; if (p.y > maxY) maxY = p.y; }
  if (!Number.isFinite(minX)) return null;
  const x0 = Math.floor(minX), y0 = Math.floor(minY);
  const w = Math.max(1, Math.ceil(maxX) - x0 + 1), h = Math.max(1, Math.ceil(maxY) - y0 + 1);
  const rowBytes = (w + 7) >> 3;
  const buf = new Uint8Array(rowBytes * h);
  let any = false;
  for (let py = 0; py < h; py++) {
    const y = y0 + py + 0.5;
    const xs: { x: number; d: number }[] = [];
    for (const c of contours) {
      for (let k = 0; k + 1 < c.length; k++) {
        const a = c[k], b = c[k + 1];
        if (a.y === b.y) continue;
        if ((a.y <= y && b.y > y) || (b.y <= y && a.y > y)) xs.push({ x: a.x + ((y - a.y) / (b.y - a.y)) * (b.x - a.x), d: b.y > a.y ? 1 : -1 });
      }
    }
    if (!xs.length) continue;
    xs.sort((p, q) => p.x - q.x);
    let wind = 0;
    for (let k = 0; k + 1 < xs.length; k++) {
      wind += xs[k].d;
      if (wind === 0) continue;
      const xa = Math.round(xs[k].x - x0), xb = Math.round(xs[k + 1].x - x0);
      for (let px = Math.max(0, xa); px < Math.min(w, xb); px++) { buf[py * rowBytes + (px >> 3)] |= 0x80 >> (px & 7); any = true; }
    }
  }
  return any ? { w, h, rowBytes, buf, x0, y0 } : null;
}

/** Thicken strokes: OR the glyph with itself shifted right `dx` and down `dy` dots (pure). */
export function dilateBits(g: GlyphBits, dx: number, dy: number): GlyphBits {
  if ((dx <= 0 && dy <= 0) || g.w === 0) return g;
  const w = g.w + dx, h = g.h + dy, rowBytes = (w + 7) >> 3;
  const buf = new Uint8Array(rowBytes * h);
  for (let y = 0; y < g.h; y++) for (let x = 0; x < g.w; x++) {
    if (!(g.buf[y * g.rowBytes + (x >> 3)] & (0x80 >> (x & 7)))) continue;
    for (let j = 0; j <= dy; j++) for (let i = 0; i <= dx; i++) { const X = x + i, Y = y + j; buf[Y * rowBytes + (X >> 3)] |= 0x80 >> (X & 7); }
  }
  return { ...g, w, h, rowBytes, buf };
}

const outlineCache = new Map<string, GlyphBits | null>();
/** One outline glyph at `px` dots per em, or null when the face has no such codepoint. */
export function outlineGlyph(face: SansFace, faceKey: string, cp: number, px: number): GlyphBits | null {
  const key = `${faceKey}|${cp}|${px}`;
  const hit = outlineCache.get(key);
  if (hit !== undefined) return hit;
  const rec = face.g[cp];
  if (rec == null) { outlineCache.set(key, null); return null; }
  const bar = rec.indexOf("|");
  const scale = px / face.upm;
  const adv = Number(rec.slice(0, bar)) * scale;
  const steps = px >= 48 ? 8 : px >= 24 ? 6 : 4;
  const contours = parseOutline(rec.slice(bar + 1), steps).map((c) => c.map((p) => ({ x: p.x * scale, y: p.y * scale })));
  const f = fillContours(contours);
  const out: GlyphBits = f ? { ...f, adv } : EMPTY_GLYPH(adv);
  outlineCache.set(key, out);
  return out;
}

// ── CJK ideograph cells (committed atlases) ───────────────────────────────────────────────────
export type CjkCell = 18 | 20 | 24 | 32;
export const CJK_CELLS: CjkCell[] = [18, 20, 24, 32];
/** The atlas cell × whole-number magnification closest to (and not above, when possible) `px`. */
export function cjkCellFor(px: number): { cell: CjkCell; mag: number } {
  let best: { cell: CjkCell; mag: number } = { cell: 18, mag: 1 };
  let bestErr = Infinity;
  for (let mag = 1; mag <= 6; mag++) for (const cell of CJK_CELLS) {
    const s = cell * mag;
    const err = s <= px + 1 ? px - s : (s - px) * 1.5; // a cell a little above the em is fine (the ideograph ink sits inside it)
    if (err < bestErr) { bestErr = err; best = { cell, mag }; }
  }
  return best;
}
const b64 = (s: string): Uint8Array => {
  const bin = typeof atob === "function" ? atob(s) : (globalThis as unknown as { Buffer: { from(a: string, e: string): { toString(e: string): string } } }).Buffer.from(s, "base64").toString("binary");
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i) & 0xff;
  return out;
};
const cjkCache = new Map<string, GlyphBits | null>();
/** An ideograph from the cell atlas, magnified, placed on the baseline of a `px`-em line. */
export function cjkGlyph(atlas: GlyphAtlas | undefined, cell: CjkCell, mag: number, cp: number, px: number): GlyphBits | null {
  const font = atlas?.cjk;
  if (!font) return null;
  const key = `${cell}|${mag}|${cp}|${px}`;
  const hit = cjkCache.get(key);
  if (hit !== undefined) return hit;
  const rows = font.glyphs[cp];
  if (!rows) { cjkCache.set(key, null); return null; }
  const src = b64(rows), srb = (font.w + 7) >> 3;
  const s = cell * mag, rowBytes = (s + 7) >> 3;
  const buf = new Uint8Array(rowBytes * s);
  for (let y = 0; y < font.h; y++) for (let x = 0; x < font.w; x++) {
    if (!(src[y * srb + (x >> 3)] & (0x80 >> (x & 7)))) continue;
    for (let j = 0; j < mag; j++) for (let i = 0; i < mag; i++) { const X = x * mag + i, Y = y * mag + j; buf[Y * rowBytes + (X >> 3)] |= 0x80 >> (X & 7); }
  }
  // em cell: baseline at 0.88·s; centred in the px-wide advance
  const out: GlyphBits = { w: s, h: s, rowBytes, buf, x0: 0, y0: -Math.round(0.88 * s), adv: s };
  cjkCache.set(key, out);
  return out;
}

// ── Fallback drawer (device fonts) ────────────────────────────────────────────────────────────
// Draws ONE run of text (a whole word or right-to-left phrase, so the browser shapes it) at `px`
// dots per em into a 1-bit picture. Returns null when nothing can be drawn (no canvas).
export interface RunDrawer { drawRun(text: string, px: number, weight: SansWeight, rtl: boolean): GlyphBits | null }
let fallbackDrawer: RunDrawer | null | undefined;
export function setFallbackRunDrawer(d: RunDrawer | null): void { fallbackDrawer = d; runCache.clear(); }
export const FALLBACK_FONTS = `"Noto Sans", "Noto Sans JP", "Noto Sans KR", "Noto Sans Thai", "Noto Sans Arabic", "Noto Sans Hebrew", "Noto Sans Devanagari", "PingFang TC", "Hiragino Sans", "Apple SD Gothic Neo", Thonburi, "Geeza Pro", "Segoe UI", "Malgun Gothic", "Leelawadee UI", Tahoma, system-ui, sans-serif`;
type Ctx2D = {
  font: string; direction?: string; textAlign?: string; textBaseline?: string; fillStyle: string;
  measureText(t: string): { width: number; actualBoundingBoxAscent?: number; actualBoundingBoxDescent?: number; actualBoundingBoxLeft?: number; actualBoundingBoxRight?: number };
  fillText(t: string, x: number, y: number): void; clearRect(x: number, y: number, w: number, h: number): void;
  getImageData(x: number, y: number, w: number, h: number): { data: Uint8ClampedArray | Uint8Array };
};
type CanvasLike = { width: number; height: number; getContext(k: "2d"): Ctx2D | null };
/** A RunDrawer over any canvas factory (the browser's, or @napi-rs/canvas in tests). */
export function canvasRunDrawer(make: (w: number, h: number) => CanvasLike | null, fonts = FALLBACK_FONTS): RunDrawer {
  return {
    drawRun(text, px, weight, rtl) {
      const probe = make(4, 4)?.getContext("2d");
      if (!probe) return null;
      const font = `${weight} ${px}px ${fonts}`;
      probe.font = font;
      const m = probe.measureText(text);
      const adv = m.width;
      const asc = Math.ceil(m.actualBoundingBoxAscent ?? px * 0.9) + 1;
      const desc = Math.ceil(m.actualBoundingBoxDescent ?? px * 0.25) + 1;
      const left = Math.ceil(m.actualBoundingBoxLeft ?? 0) + 1;
      const w = Math.max(1, Math.ceil(Math.max(adv, (m.actualBoundingBoxRight ?? adv))) + left + 2);
      const h = Math.max(1, asc + desc);
      const cv = make(w, h);
      const ctx = cv?.getContext("2d");
      if (!cv || !ctx) return null;
      ctx.clearRect(0, 0, w, h);
      ctx.font = font;
      ctx.fillStyle = "#000";
      ctx.textBaseline = "alphabetic";
      if (rtl) { ctx.direction = "rtl"; ctx.textAlign = "right"; ctx.fillText(text, left + adv, asc); }
      else { ctx.direction = "ltr"; ctx.textAlign = "left"; ctx.fillText(text, left, asc); }
      const data = ctx.getImageData(0, 0, w, h).data;
      const rowBytes = (w + 7) >> 3;
      const buf = new Uint8Array(rowBytes * h);
      let any = false;
      for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) if (data[(y * w + x) * 4 + 3] >= 128) { buf[y * rowBytes + (x >> 3)] |= 0x80 >> (x & 7); any = true; }
      if (!any) return EMPTY_GLYPH(adv);
      return { w, h, rowBytes, buf, x0: -left, y0: -asc, adv };
    },
  };
}
function browserDrawer(): RunDrawer | null {
  if (typeof document === "undefined") return null;
  return canvasRunDrawer((w, h) => {
    try {
      const c = document.createElement("canvas");
      c.width = w; c.height = h;
      const ctx = c.getContext("2d", { willReadFrequently: true } as CanvasRenderingContext2DSettings);
      return ctx ? ({ width: w, height: h, getContext: () => ctx as unknown as Ctx2D }) : null;
    } catch { return null; }
  });
}
const runCache = new Map<string, GlyphBits | null>();
/** Draw a run with the fallback drawer (cached). null = no drawer / nothing drawn. */
export function fallbackRun(text: string, px: number, weight: SansWeight, rtl: boolean): GlyphBits | null {
  if (fallbackDrawer === undefined) fallbackDrawer = browserDrawer();
  if (!fallbackDrawer) return null;
  const key = `${weight}|${px}|${rtl ? 1 : 0}|${text}`;
  const hit = runCache.get(key);
  if (hit !== undefined) return hit;
  let out: GlyphBits | null;
  try { out = fallbackDrawer.drawRun(text, px, weight, rtl); } catch { out = null; }
  runCache.set(key, out);
  return out;
}
export function __clearGlyphCaches(): void { outlineCache.clear(); cjkCache.clear(); runCache.clear(); }
